INSERT INTO `plant_species` (`name`,`emoji`,`category`,`soil_min`,`soil_max`,`temp_min`,`temp_max`,`light_level`,`water_cycle`,`fertilize_cycle`,`care_tips`,`diseases`,`growth_stages`) VALUES
('水稻','🌾','crop',70,100,20,35,'喜光',1,30,'浅水勤灌，分蘖期晒田控苗，抽穗期保水，成熟期落干','稻瘟病,稻飞虱,纹枯病','[{"stage":"育秧期","days":15,"desc":"保持秧田湿润，防寒防病虫害"},{"stage":"分蘖期","days":30,"desc":"浅水勤灌促分蘖，适时晒田控无效分蘖"},{"stage":"拔节孕穗期","days":25,"desc":"需水高峰期，保持水层"},{"stage":"抽穗扬花期","days":15,"desc":"浅水灌溉，防稻飞虱"},{"stage":"灌浆成熟期","days":30,"desc":"干湿交替，成熟前落干便于收割"}]'),  -- 第 1 行：水稻，category 为 crop；从第 16 行起 category 变成 pot
('玉米','🌽','crop',60,80,20,32,'喜光',3,30,'苗期控水蹲苗，大喇叭口期重施穗肥，抽雄期防旱','玉米螟,大斑病,纹枯病','[{"stage":"苗期","days":25,"desc":"适度控水促根系下扎"},{"stage":"拔节期","days":25,"desc":"需水增多，追施拔节肥"},{"stage":"抽雄吐丝期","days":15,"desc":"需水临界期，防干旱"},{"stage":"灌浆成熟期","days":35,"desc":"保持土壤湿润，防早衰"}]'),
('花生','🥜','crop',50,70,20,30,'喜光',4,25,'苗期促根，开花下针期追肥培土，结荚期防旱涝','叶斑病,青枯病,根结线虫','[{"stage":"苗期","days":25,"desc":"保持土壤湿润促出苗"},{"stage":"开花下针期","days":30,"desc":"追施氮肥，保持湿润利于下针"},{"stage":"结荚期","days":30,"desc":"控水防烂果，适时培土"},{"stage":"饱果成熟期","days":25,"desc":"控水促荚果饱满"}]'),
('甘蔗','🍬','crop',60,80,22,35,'喜光',4,30,'伸长期大肥大水，成熟期控水增糖，剥除枯叶','螟虫,赤腐病,梢腐病','[{"stage":"萌芽出苗期","days":40,"desc":"保持土壤湿润，防干旱板结"},{"stage":"分蘖期","days":40,"desc":"追施分蘖肥，中耕培土"},{"stage":"茎伸长期","days":120,"desc":"需水需肥高峰，大培土"},{"stage":"工艺成熟期","days":60,"desc":"控水停肥，促进糖分积累"}]'),
('番茄','🍅','crop',45,65,18,30,'喜光',2,15,'定植缓苗控水，结果期多施磷钾肥，需搭架整枝，防早疫晚疫','晚疫病,青枯病,病毒病,白粉虱','[{"stage":"苗期","days":30,"desc":"控制浇水防徒长，苗龄 30 天可定植"},{"stage":"开花坐果期","days":30,"desc":"花期控水，坐果后追施磷钾肥"},{"stage":"结果期","days":60,"desc":"保持湿润防裂果，及时采收"}]'),
('辣椒','🌶️','crop',40,60,18,30,'喜光',2,15,'苗期防徒长，花期控水，结果期勤施肥，防病毒病','炭疽病,病毒病,白粉虱,蓟马','[{"stage":"苗期","days":35,"desc":"控水蹲苗，防徒长"},{"stage":"开花坐果期","days":30,"desc":"花期控水，坐果后追肥"},{"stage":"结果期","days":60,"desc":"保持湿润，采收期可追钾肥"}]'),
('黄瓜','🥒','crop',50,70,20,30,'喜光',2,15,'苗期少浇水，结瓜期需水多，及时绑蔓摘侧芽，防霜霉白粉','霜霉病,白粉病,角斑病','[{"stage":"苗期","days":25,"desc":"控水促根，防治猝倒病"},{"stage":"抽蔓开花期","days":20,"desc":"搭架绑蔓，追施提苗肥"},{"stage":"结果期","days":50,"desc":"需水需肥高峰，见干见湿"}]'),
('豆角','🫛','crop',45,65,20,32,'喜光',3,20,'苗期控水，开花结荚期需水多，及时搭架引蔓','锈病,蚜虫,白粉病','[{"stage":"苗期","days":25,"desc":"控水防徒长，及时插架"},{"stage":"抽蔓期","days":15,"desc":"引蔓上架，追施薄肥"},{"stage":"开花结荚期","days":50,"desc":"需水需肥高峰，防落花落荚"}]'),
('西瓜','🍉','crop',40,60,22,35,'喜光',3,20,'伸蔓期追肥，坐瓜后需水多，采收前一周控水增甜','枯萎病,白粉病,病毒病','[{"stage":"苗期","days":30,"desc":"控水促根，防猝倒病"},{"stage":"抽蔓期","days":25,"desc":"追施伸蔓肥，整枝压蔓"},{"stage":"开花坐瓜期","days":20,"desc":"人工授粉，坐瓜后追肥"},{"stage":"果实膨大期","days":25,"desc":"需水高峰，保持湿润"},{"stage":"成熟期","days":15,"desc":"控水增甜，防裂瓜"}]'),
('红薯','🍠','crop',45,65,20,32,'喜光',5,25,'前期促苗，中后期控水防徒长，块根膨大期追钾肥','黑斑病,茎线虫病,甘薯天蛾','[{"stage":"发根还苗期","days":20,"desc":"浇足定根水，查苗补苗"},{"stage":"分枝结薯期","days":40,"desc":"控水防徒长，中耕培土"},{"stage":"薯块膨大期","days":60,"desc":"保持湿润，追施钾肥"},{"stage":"收获期","days":30,"desc":"控水，收前割藤晒地"}]'),
('木薯','🪵','crop',45,65,22,35,'喜光',7,40,'耐旱，块根形成期控水，膨大期保墒，防病毒病','花叶病,褐斑病,根腐病','[{"stage":"出苗期","days":30,"desc":"保持土壤湿润促出苗"},{"stage":"块根形成期","days":60,"desc":"控水防烂根，中耕除草"},{"stage":"块根膨大期","days":120,"desc":"保持土壤湿润，追施钾肥"},{"stage":"收获期","days":30,"desc":"停水，收前割秆"}]'),
('香蕉','🍌','crop',60,80,22,32,'喜光',3,20,'需水量大，保持土壤湿润，施足有机肥，防风','叶斑病,束顶病,象鼻虫','[{"stage":"苗期","days":60,"desc":"保持湿润，薄肥勤施"},{"stage":"营养生长期","days":120,"desc":"需水需肥高峰，勤施薄肥"},{"stage":"现蕾抽蕾期","days":30,"desc":"控水防烂蕾，留蕉保护"},{"stage":"果实发育期","days":60,"desc":"保持湿润，套袋防虫"},{"stage":"成熟期","days":30,"desc":"控水，适时采收"}]'),
('荔枝','🍒','crop',50,70,18,32,'喜光',5,30,'花前控水促花芽，果实发育期保水，防裂果','霜疫霉病,蒂蛀虫,炭疽病','[{"stage":"新梢生长期","days":60,"desc":"适度供水促梢，防治梢期害虫"},{"stage":"花芽分化期","days":45,"desc":"控水控梢促花芽分化"},{"stage":"开花坐果期","days":25,"desc":"花期防雨冲花，保花保果"},{"stage":"果实发育期","days":60,"desc":"保持湿润防裂果，追施壮果肥"},{"stage":"成熟期","days":15,"desc":"控水增甜，防鸟防虫"}]'),
('火龙果','🐉','crop',40,60,20,35,'喜光',5,25,'耐旱，花期保水，结果期追磷钾肥，注意防茎腐','茎腐病,炭疽病,蚧壳虫','[{"stage":"幼苗期","days":60,"desc":"适当遮阴，保持土壤湿润"},{"stage":"营养生长期","days":90,"desc":"搭架引蔓，薄肥勤施"},{"stage":"现蕾开花期","days":30,"desc":"花期保持湿润，人工授粉"},{"stage":"果实发育期","days":30,"desc":"保持湿润，追施磷钾肥"},{"stage":"成熟期","days":15,"desc":"控水，成熟后及时采收"}]'),
('柑橘','🍊','crop',50,70,15,30,'喜光',5,30,'花前控水，果实膨大期保水，冬季清园防黄龙病','黄龙病,红蜘蛛,溃疡病','[{"stage":"春梢生长期","days":45,"desc":"适度供水，疏除过多春梢"},{"stage":"花蕾期","days":20,"desc":"保花保果，防治花蕾蛆"},{"stage":"开花坐果期","days":30,"desc":"花期防雨，稳果后追肥"},{"stage":"果实膨大期","days":120,"desc":"需水高峰，保持湿润防裂果"},{"stage":"果实成熟期","days":60,"desc":"控水增糖，防霜冻"}]'),
('茉莉花','🌷','pot',45,65,18,32,'喜光',3,15,'喜阳光充足，花后及时修剪残花，勤施薄肥，冬季保暖','白粉病,红蜘蛛,叶斑病','[{"stage":"幼苗期","days":30,"desc":"薄肥勤施，促分枝"},{"stage":"营养生长期","days":45,"desc":"勤修剪促新枝，每周施稀薄液肥"},{"stage":"现蕾期","days":20,"desc":"增施磷钾肥促花蕾"},{"stage":"开花期","days":9999,"desc":"花后立即修剪，勤施薄肥，保持阳光充足"}]'),  -- 第 16 行：茉莉花，category 为 pot（从这里开始以下 5 行都是盆栽）
('绿萝','🌿','pot',40,60,18,30,'散光',4,30,'喜湿润半阴环境，土壤干透浇透，避免强光直晒','白粉病,叶斑病,红蜘蛛','[{"stage":"缓苗期","days":15,"desc":"置于半阴处，保持土壤湿润"},{"stage":"生长期","days":9999,"desc":"干透浇透，每月施一次稀薄液肥"}]'),
('薄荷','🍃','pot',40,60,15,30,'喜光',2,20,'喜阳光喜水，摘心促进分枝，可定期采收嫩叶','锈病,白粉病,蚜虫','[{"stage":"幼苗期","days":20,"desc":"保持湿润，摘心促分枝"},{"stage":"生长期","days":9999,"desc":"勤浇水保持湿润，定期采收嫩叶"}]'),
('多肉植物','🌵','pot',10,25,15,28,'喜光',10,45,'宁干勿湿，土壤完全干透再浇，夏季休眠期停水停肥','根腐病,介壳虫,软腐病','[{"stage":"缓苗期","days":30,"desc":"控水，遮阴缓苗"},{"stage":"生长期","days":9999,"desc":"干透浇透，夏季休眠控水停肥"}]'),
('月季','🌹','pot',45,65,15,28,'喜光',3,20,'喜光喜肥，花后重剪，薄肥勤施，防白粉黑斑','白粉病,黑斑病,蚜虫','[{"stage":"幼苗期","days":40,"desc":"薄肥勤施，促壮苗"},{"stage":"营养生长期","days":60,"desc":"勤修剪，每周施液肥"},{"stage":"现蕾期","days":20,"desc":"增施磷钾肥促花蕾"},{"stage":"开花期","days":90,"desc":"花后修剪，防治白粉病黑斑病"}]');
INSERT INTO `plant_disease` (`name`,`plants`,`symptom`,`cause`,`season`,`prevention`,`drug`) VALUES
('稻瘟病','水稻','叶片褐色梭形病斑，穗颈变黑枯死','高湿、偏施氮肥、低温','夏秋季','浅水勤灌、合理施氮、田间晾晒','三环唑或稻瘟灵 500 倍液，7 天 1 次连喷 2 次'),
('稻飞虱','水稻','成若虫群集稻丛基部吸汁，叶黄枯死','高温高湿、种植过密','夏秋季','浅水勤灌、保护天敌、压低虫源','吡虫啉或烯啶虫胺 1500 倍液喷茎基部'),
('纹枯病','水稻,玉米','叶鞘出现云纹状病斑，茎秆软腐','高温高湿、密度过大、施氮偏多','夏秋季','合理密植、控氮增钾、晒田','井冈霉素 500 倍液，7 天 1 次连喷 2 次'),
('玉米螟','玉米','心叶被蛀呈排孔状，茎秆折倒','越冬虫源、种植连作','夏秋季','处理秸秆、心叶撒施颗粒剂','辛硫磷颗粒剂撒心叶，或氯虫苯甲酰胺喷雾'),
('大斑病','玉米','叶片大形灰褐色病斑，严重时整叶枯死','高温多雨、连作、品种感病','夏秋季','轮作、合理密植、清除病残体','苯醚甲环唑或代森锰锌 800 倍液喷雾'),
('花生叶斑病','花生','叶面褐色圆形病斑，后期穿孔落叶','高湿、连作、氮肥偏多','夏秋季','轮作、平衡施肥、清除病叶','百菌清或苯醚甲环唑 800 倍液，10 天 1 次'),
('青枯病','花生,番茄,辣椒','晴天中午整株萎蔫，茎部维管束褐变','高温高湿、连作、根部伤口','夏季','轮作、石灰消毒土壤、拔除病株','农用链霉素或可杀得 500 倍液灌根'),
('螟虫（甘蔗）','甘蔗','茎部蛀孔，枯心苗，茎秆易折断','越冬幼虫、田间残株','夏秋季','清除残株、释放赤眼蜂、剥除枯叶','杀虫双或氯虫苯甲酰胺喷雾'),
('甘蔗赤腐病','甘蔗','茎内组织红色带白斑，有酸酒味','高温高湿、蔗种带菌','夏秋季','选无病种茎、轮作、砍收及时','多菌灵 500 倍液浸种 10 分钟'),
('晚疫病','番茄','叶缘水渍状暗绿斑，果实褐色硬斑，湿度大时叶背白霉','高湿多雨、温度 18-22℃ 易发','春秋季','控水通风、及时摘除病果病叶','甲霜灵锰锌 500 倍液，7 天 1 次连喷 3 次'),
('番茄病毒病','番茄,辣椒','叶片黄绿花叶、皱缩畸形，植株矮化','蚜虫传毒、高温干旱','夏秋季','治蚜防病、选用抗病品种、拔除病株','防蚜为主，20% 病毒 A 可湿粉 500 倍液'),
('辣椒炭疽病','辣椒','果实水渍状凹陷斑，上生轮纹状小黑点','高湿多雨、连作','夏秋季','轮作、通风透光、及时采收','咪鲜胺或炭特灵 1000 倍液喷雾'),
('霜霉病','黄瓜,葡萄','叶面黄斑，叶背灰色霜霉层，叶片枯死','低温高湿、通风差','春秋季','通风降湿、避免叶面积水','烯酰吗啉或甲霜灵锰锌 600 倍液喷雾'),
('白粉病','黄瓜,西瓜,月季,茉莉,绿萝','叶片表面白色粉状霉层，严重时卷曲枯黄','高温高湿、通风不良、昼夜温差大','夏秋季','加强通风、降低湿度、及时摘除病叶','多菌灵或粉锈宁 500-800 倍液，7 天 1 次连喷 2 次'),
('西瓜枯萎病','西瓜','藤蔓萎蔫，茎基部维管束褐变，有粉红霉层','连作、高温、根伤','夏季','轮作 5 年以上、嫁接育苗、拔除病株','多菌灵 500 倍液灌根，每 7 天 1 次'),
('红薯黑斑病','红薯','薯块黑褐色病斑，有苦味，窖藏期烂薯','种薯带菌、伤口感染','全年','选用无病种薯、温汤浸种、窖藏消毒','多菌灵 500 倍液浸薯种 10 分钟'),
('香蕉叶斑病','香蕉','叶片长条状褐色病斑，叶缘干枯','高湿多雨、偏施氮肥','雨季','清沟排水、合理密植、摘除病叶','丙环唑或苯醚甲环唑 1000 倍液喷雾'),
('柑橘黄龙病','柑橘','叶片斑驳黄化，果实畸形不熟，整株衰退','木虱传播、带病苗木','全年','检疫无病苗木、防木虱、砍除病树','防柑橘木虱：吡虫啉 1500 倍液；病树必砍'),
('柑橘溃疡病','柑橘','叶片果实圆形油渍状病斑，木栓化凸起','高温多雨、风伤虫伤','夏秋季','防风雨伤口、喷药保护幼果','氢氧化铜或噻菌铜 800 倍液，10 天 1 次'),
('红蜘蛛','茉莉,柑橘,草莓,月季','叶背细小红色虫体和蛛网，叶片灰白小点','干燥高温、通风差','夏季','增加空气湿度、经常喷水洗叶','阿维菌素或哒螨灵 1500 倍液，重点喷叶背'),
('蚜虫','豆角,薄荷,茉莉,辣椒','嫩叶背面聚集绿色/黑色小虫，叶片卷曲变形','温暖潮湿、新梢嫩叶期','春季','剪除虫枝、黄板诱杀','吡虫啉或苦参碱 1000 倍液喷雾'),
('锈病','豆角,薄荷,月季','叶背橙黄色粉状孢子堆，叶片卷曲早落','高温高湿、偏施氮肥','夏秋季','加强通风、平衡施肥、清除落叶','三唑酮或烯唑醇 800 倍液喷雾');
