-- 品种库改造：15 广西农作物 + 5 盆栽（可重跑）
USE farm_db;

-- ---------- 1. plant_species 加列 ----------
SET @c1 = (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='farm_db' AND TABLE_NAME='plant_species' AND COLUMN_NAME='category');  -- 查 plant_species 表里有没有 category 列
SET @sql1 = IF(@c1=0, "ALTER TABLE `plant_species` ADD COLUMN `category` varchar(10) DEFAULT 'crop' COMMENT '分类:crop农作物/pot盆栽', ADD COLUMN `growth_stages` json DEFAULT NULL COMMENT '生长阶段模型[{\"stage\":\"幼苗期\",\"days\":20,\"desc\":\"...\"}]'", 'SELECT 1');  -- 一次 ALTER 加两列：category 默认 crop；growth_stages 是 JSON 列，可空
PREPARE st1 FROM @sql1; EXECUTE st1; DEALLOCATE PREPARE st1;  -- 预处理 → 执行 → 释放

-- ---------- 2. 清空旧数据重灌（品种全换） ----------
DELETE FROM plant_species;  -- 清空旧品种数据
ALTER TABLE plant_species AUTO_INCREMENT = 1;  -- 自增计数器归 1，重灌后 id 从 1 开始

-- 20 个品种，id 依次为：1 水稻 / 2 玉米 / 3 花生 / 4 甘蔗 / 5 番茄 / 6 辣椒 / 7 黄瓜 / 8 豆角 /

-- ---------- 3. 病虫害库全量换农作物（可重跑） ----------
DELETE FROM plant_disease;  -- 清空旧病虫害数据
ALTER TABLE plant_disease AUTO_INCREMENT = 1;  -- 自增计数器归 1
-- plants 列写易感植物名（逗号分隔），后端拿它跟用户实际种的植物名比对，决定推不推预防提醒。

-- ---------- 4. 核对 ----------
SELECT category, COUNT(*) AS cnt FROM plant_species GROUP BY category;  -- 按 crop / pot 分组数品种个数
SELECT COUNT(*) AS disease_count FROM plant_disease;  -- 数病虫害总条数
